-- Nieuwe vacature: Senior AI consultant & Forward Deployed Engineer (5 november 2026).
--
-- De tekst komt uit de vacature op LinkedIn en is met dezelfde plakfunctie opgemaakt als de
-- nieuwe vacature-editor (tests/fixtures/vacature-ai.txt). Hij staat op CONCEPT: pas na je eigen
-- controle zet je hem in /admin/vacatures op Live. De eerste alinea van de tekst is de intro in
-- de header; er is dus geen aparte intro-sleutel.
--
-- Idempotent: bestaat de slug al, dan blijft die rij ongemoeid (zodat een bewerking in de admin
-- niet wordt overschreven). Controleer onderaan wat er staat.

insert into cms_vacatures (slug, titel, status, volgorde, data)
values (
  'senior-ai-consultant-forward-deployed-engineer',
  'Senior AI consultant & Forward Deployed Engineer',
  'concept',
  0,
  $json${"functietitel":"Senior AI consultant & Forward Deployed Engineer","discipline":"AI · Senior","locatie":"Utrecht / hybride","tags":["AI","Senior","Utrecht / hybride"],"inhoud":"<h2>Over de rol</h2><p>The New Wave IT helpt organisaties bij de transformatie naar een AI-native organisatie. We combineren strategisch AI-advies met het daadwerkelijk ontwikkelen en implementeren van AI-oplossingen.</p><p>Als Senior AI Engineer / Forward Deployed Engineer werk je direct bij onze klanten aan concrete AI-vraagstukken. Je vertaalt bedrijfsprocessen en uitdagingen naar schaalbare, veilige en productieklare AI-oplossingen.</p><p>Je bent niet alleen een technisch specialist, maar begrijpt ook de business. Je werkt nauw samen met stakeholders, identificeert kansen en neemt verantwoordelijkheid voor de volledige technische realisatie: van prototype tot productie.</p><h2>Wat ga je doen?</h2><ul><li><p>Bedrijfsprocessen analyseren en kansen identificeren voor AI en automatisering.</p></li><li><p>AI-agents en LLM-gebaseerde applicaties ontwerpen, ontwikkelen en implementeren.</p></li><li><p>AI-oplossingen integreren met bestaande enterprise-systemen, databases en API's.</p></li><li><p>RAG-oplossingen, tool calling en agentic workflows ontwikkelen.</p></li><li><p>AI-prototypes doorontwikkelen naar betrouwbare productieoplossingen.</p></li><li><p>Zorgen voor AI-security, monitoring, evaluatie, schaalbaarheid en beheersbare operationele kosten (zoals tokenverbruik).</p></li><li><p>Technische keuzes onderbouwen en stakeholders adviseren over AI-architectuur.</p></li><li><p>Zelfstandig werken binnen complexe klantomgevingen en multidisciplinaire teams.</p></li></ul><h2>Wat breng je mee?</h2><h3>Must-haves</h3><h3>Software engineering</h3><p>Hbo/wo werk- en denkniveau, bij voorkeur met een relevante technische opleiding (sterke voorkeur voor Informatica).</p><p>Uitstekende beheersing van de Nederlandse taal, mondeling en schriftelijk.</p><ul><li><p>Minimaal 5 jaar professionele softwareontwikkeling.</p></li><li><p>Uitstekende kennis van Python.</p></li><li><p>Ervaring met API-ontwikkeling, REST-integraties, SQL en databases.</p></li><li><p>Ervaring met softwarearchitectuur, testing en versiebeheer.</p></li></ul><h3>AI engineering</h3><ul><li><p>Praktijkervaring met Large Language Models en model-API's.</p></li><li><p>Ervaring met RAG, embeddings en vector databases.</p></li><li><p>Ervaring met AI-agents, function/tool calling en workfloworkestratie.</p></li><li><p>Kennis van prompt engineering, evaluatie, betrouwbaarheid en kostenoptimalisatie van AI-systemen (modelkeuze en tokenverbruik).</p></li></ul><h3>Cloud &amp; production engineering</h3><ul><li><p>Ervaring met Azure en/of AWS.</p></li><li><p>Kennis van Docker, CI/CD en deployment.</p></li><li><p>Ervaring met security, logging en monitoring, inclusief veilige LLM-integraties, toegangsbeheer en bescherming tegen prompt injection.</p></li><li><p>Aantoonbare ervaring met het naar productie brengen van software- of AI-oplossingen.</p></li></ul><h3>Consultancy &amp; business</h3><ul><li><p>Ervaring in complexe enterprise-omgevingen.</p></li><li><p>Sterke communicatieve vaardigheden en stakeholdermanagement.</p></li><li><p>Vermogen om bedrijfsproblemen te vertalen naar technische oplossingen.</p></li><li><p>Zelfstandig kunnen opereren bij klanten.</p></li></ul><h3>Nice-to-haves</h3><ul><li><p>Ervaring met LangChain, LangGraph of vergelijkbare agentframeworks.</p></li><li><p>Ervaring met n8n of andere orkestratieplatformen.</p></li><li><p>Kennis van machine learning, scikit-learn en voorspellende modellen.</p></li><li><p>Ervaring met data pipelines, modelvalidatie en MLOps.</p></li><li><p>Ervaring met Siemens AI Studio / RapidMiner.</p></li><li><p>Kennis van Mendix of andere enterprise low-code-platformen.</p></li></ul><h2>Wat bieden wij jou?</h2><ul><li><p>Een bruto maandsalaris van € 5.000 tot € 6.500 op basis van 40 uur, afhankelijk van ervaring en expertise.</p></li><li><p>Een jaarlijkse bonusregeling tot maximaal 1,5 bruto maandsalaris.</p></li><li><p>Een business-ov-kaart, een reiskostenvergoeding of een combinatie daarvan. Wij bieden geen leaseauto.</p></li><li><p>Pensioen via StiPP met een werkgeversbijdrage van 15,9%.</p></li><li><p>Onbeperkt verlof, in overleg met je team en de klant.</p></li><li><p>Hybride werken: bij de klant, op ons kantoor in hartje Utrecht en vanuit huis.</p></li></ul><h2>Wat maakt deze rol bijzonder?</h2><p>Je werkt op het snijvlak van AI, software engineering en bedrijfsprocessen.</p><p>Waar traditionele AI-specialisten zich vaak richten op modellen en experimenten, ben jij verantwoordelijk voor de daadwerkelijke toepassing van AI binnen organisaties.</p><p>Je combineert technische diepgang met pragmatische implementatiekracht.</p><p>Je krijgt bovendien de mogelijkheid om nieuwe technologieën zoals Siemens AI Studio te verkennen en daarmee bij te dragen aan de verdere ontwikkeling van onze AI-dienstverlening.</p><h2>Wat zoeken we nadrukkelijk niet?</h2><ul><li><p>Een pure data scientist die voornamelijk modellen onderzoekt.</p></li><li><p>Een prompt engineer zonder stevige software-engineeringachtergrond.</p></li><li><p>Een AI-strateeg zonder aantoonbare implementatie-ervaring.</p></li><li><p>Een junior AI-developer die nog intensieve technische begeleiding nodig heeft.</p></li></ul>","facts":{"team":"","niveau":"","locatie":"","uren":"","salaris":""},"employmentType":"FULL_TIME","gepubliceerdOp":"2026-11-05"}$json$::jsonb
)
on conflict (slug) do nothing;

-- Controle: de rij hoort er te staan, op concept, met een gevulde tekst.
select slug, titel, status, data ? 'inhoud' as heeft_tekst, length(data->>'inhoud') as tekens
from cms_vacatures
order by volgorde, slug;
